func TestHubMalformedBody(t *testing.T) {
	hubServer(t, 200, "<html>not json</html>")
	if _, _, err := search(t, Target{}, Query{Text: "nginx"}); err == nil {
		t.Fatal("want an error on a non-JSON body")
	}
}

